using System;
using System.Reflection;

namespace Lite.Procedures.Generated
{
    /// <summary>
    /// Discovers the generated pipeline registry from loaded assemblies (generated by Lite.Procedures.SourceGenerators).
    /// </summary>
    public static class GeneratedPipelineRegistryDiscovery
    {
        /// <summary>
        /// Well-known type name of the generated registry class.
        /// </summary>
        public const string GeneratedRegistryTypeName = "Lite.Procedures.Generated.GeneratedPipelineRegistry";

        /// <summary>
        /// Tries to find and instantiate the generated registry in the current app domain. Returns null if not found.
        /// </summary>
        public static IGeneratedPipelineRegistry? TryDiscover()
        {
            foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                try
                {
                    var type = assembly.GetType(GeneratedRegistryTypeName);
                    if (type == null)
                        continue;

                    if (!typeof(IGeneratedPipelineRegistry).IsAssignableFrom(type))
                        continue;

                    var instance = Activator.CreateInstance(type);
                    if (instance is IGeneratedPipelineRegistry registry)
                        return registry;
                }
                catch
                {
                    // Ignore load/reflection errors (e.g. dynamic assemblies)
                }
            }

            return null;
        }
    }
}
